problems.solution_code:
#include <iostream>
using namespace std;

struct Rect {
    int w;
    int h;
};

struct Result {
    int area;
    int perimeter;
};

Result calc(Rect r) {
    Result res;
    res.area = r.w * r.h;
    res.perimeter = 2 * (r.w + r.h);
    return res;
}

int main() {
    Rect r;
    cin >> r.w >> r.h;

    Result out = calc(r);

    cout << "面积：" << out.area << endl;
    cout << "周长：" << out.perimeter << endl;
    return 0;
}

