#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

struct Student {
    string name;
    int score;
};

bool cmp(const Student &x, const Student &y) {
    if (x.score != y.score) {
        return x.score > y.score;
    }
    return x.name < y.name;
}

int main() {
    int n;
    cin >> n;
    Student a[105];
    for (int i = 0; i < n; i++) {
        cin >> a[i].name >> a[i].score;
    }

    sort(a, a + n, cmp);

    for (int i = 0; i < n; i++) {
        cout << a[i].name << " " << a[i].score << endl;
    }
    return 0;
}

